#!/bin/zsh
# Real Symfony 8 app (bench/sfapp) behind php -S with N workers, load generated by ab.
# Usage: PHP=... NOCOPY_SO=... APCU_SO=... APP=/path/to/app-with-vendor [WORKERS=8 REQS=20000 CONC=8] bench/sfapp.sh
: ${PHP:?} ${NOCOPY_SO:?} ${APCU_SO:?} ${APP:?}
W=${WORKERS:-8}; N=${REQS:-20000}; C=${CONC:-8}; PORT=8099
COMMON="-d apc.enable_cli=1 -d apc.shm_size=256M -d apc.entries_hint=20000 -d memory_limit=1G -d zend_extension=opcache -d opcache.enable_cli=1 -d opcache.validate_timestamps=0"
URLS=(hello 'products?page=3' product/77 validate)
run_cfg() { name=$1; shift
  rm -rf $APP/var/cache/*
  (cd $APP/public && PHP_CLI_SERVER_WORKERS=$W $PHP -n "$@" ${=COMMON} -S 127.0.0.1:$PORT index.php >/dev/null 2>&1 &)
  sleep 2
  for u in $URLS; do curl -s -o /dev/null "127.0.0.1:$PORT/$u"; done   # build container + fill caches
  ab -q -n 2000 -c $C "127.0.0.1:$PORT/products?page=3" >/dev/null 2>&1   # warm opcache in every worker
  for u in $URLS; do   # median of 3 runs
    for i in 1 2 3; do
      ab -q -n $N -c $C "127.0.0.1:$PORT/$u" 2>/dev/null | awk '/Requests per second/{r=$4} /^ +50%/{p50=$2} /^ +99%/{p99=$2} /Failed requests/{f=$3} END{print r, p50, p99, f}'
    done | sort -n | sed -n 2p | awk -v n=$name -v u=$u '{printf "%s\t%s\t%.0f\t%s\t%s\t%s\n", n, u, $1, $2, $3, $4}'
  done
  pkill -f "127.0.0.1:$PORT"; sleep 1
}
{ # Symfony's default pool serializes values itself (DefaultMarshaller): the extension only sees strings
  RAW= run_cfg "apcu / default pool" -d extension=$APCU_SO -d apc.serializer=default
  RAW= run_cfg "nocopy / default pool" -d extension=$NOCOPY_SO -d nocopy.request_scope=1
  # a pool without the marshaller: PHP values reach the extension
  RAW=1 run_cfg "apcu / raw pool" -d extension=$APCU_SO -d apc.serializer=default
  RAW=1 run_cfg "nocopy copy / raw pool" -d extension=$NOCOPY_SO -d nocopy.request_scope=0
  RAW=1 run_cfg "nocopy zero / raw pool" -d extension=$NOCOPY_SO -d nocopy.request_scope=1; } | tee ${OUT:-/dev/null}
